# Rapanor (Carpathia No. 10161) sculpted from nothing on the skeleton and clips of the game's own export of it
# (sculptkit.py), grown from Rapanel (sibling("rapanel")): its coiled shell swept along the drifting spiral with its
# ridges and brown bands, the white eye ball on its stalk and the way of laying it, the speckles.
#   blender --background --factory-startup --python sculpts/rapanor.py -- <the export's Rapanor.glb> <out.glb>
#
# The game has no sculptor of its own for Rapanor: its export is a body generated by rule (a spider on four leg bones),
# of which only the bones, the clips and the size are taken; the snail is built to the length of its longest side.
#
# The design, from the project's picture (docs/art/reference/gemini/carpathia/10161-Rapanor.jpg): a big predatory sea
# snail. The shell is Rapanel's grown huge and heavy, its ridges deeper, a duller cream with brown bands, crusted with
# white chalk and with clusters of barnacles (small white cones with a dark hole) on its top and side. A massive grey
# body, lumpy and speckled, with a broad foot running back under the shell; at the front a heavy grey hood with two
# stalks drooping forward from it, the eyes half lidded and looking down at the prey; under the hood a great bright
# orange mouth opening wide, a darker throat and a paler tongue; two thick lobed arms of the foot gripping a dark
# blue mussel shell under the mouth.
# The skeleton: body (0, 0, 0.223), head (0, -0.117, 0.223), legs at (+-0.21, +-0.086, 0.201): the foot, arms and
# mussel stay on body (a snail's foot on leg bones would be pulled apart from the mussel), the hood, stalks and mouth
# on head; the leg bones carry nothing.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import Kit, ell, tube, sheet, lathe, srgb, inside, unit, eye_look, outward, args, sibling

rp = sibling("rapanel")

SHELL, BAND, LINING, CRUST, BARN, HOLE = "#DCCFAE", "#86663F", "#B9A17C", "#F1EEE6", "#C9C2B4", "#988C7C"
BODY, SPECK, PALE = "#6E8595", "#516474", "#8DA2B0"
ORANGE, THROAT, TONGUE, LIP = "#F06A28", "#A8301A", "#F79A5A", "#E8571E"
MUSSEL, MUSSEL2, MLINE = "#2D3150", "#3E4568", "#59628C"
WHITE, INK, IRIS = rp.WHITE, rp.INK, rp.IRIS

CC = np.array([0.0, 0.13, 0.64])           # the shell's coil
HOOD_C, HOOD_R = np.array([0.0, -0.33, 0.56]), np.array([0.175, 0.17, 0.12])
BALL_R = 0.042
BALL_C = np.array([0.105, -0.495, 0.715])
EYE_D = (0.3, -0.85, -0.25)                 # looking forward and down at its prey
MOUTH_C, MOUTH_N = np.array([0.035, -0.462, 0.345]), rp.unit(0.2, -1, -0.12)
MUS_C = np.array([0.01, -0.52, 0.115])


def frame(n):
    n = np.array(n, float); n /= np.linalg.norm(n)
    a = np.cross(n, (0, 0, 1.0)); a /= np.linalg.norm(a)
    return a, np.cross(n, a), n


def on_shell(sh, th, phi):
    """A point of the shell's outer surface and its outward normal."""
    p = sh.at(np.array(th, float), np.array(phi, float))
    a = sh.at(np.array(th + 1.0), np.array(phi)) - p
    b = sh.at(np.array(th), np.array(phi + 0.02)) - p
    n = np.cross(a, b)
    mid = sh.at(np.array(th), np.array(phi), scale=0.3)
    if np.dot(n, p - mid) < 0:
        n = -n
    return p, n / np.linalg.norm(n)


def crust(k, sh, th, phi, dth, dphi, seed, lift=0.007):
    """A chalky white patch on the shell, its outline blotched."""
    def at(u, v):
        w = 0.55 + 0.45 * np.sin(math.pi * u) ** 0.6 * (1 + 0.25 * np.sin(u * 9 + seed))
        return sh.at(th + (u - 0.5) * dth, phi + (v - 0.5) * dphi * w, off=lift)
    k.add(f"crust{seed}", outward(sheet(at, 16, 12, 0.006)), CRUST, "body", fuse=False, surface="shell")


def barnacle(k, name, p, n, r, bone="body"):
    """A barnacle: a squat white cone with a dark hole at its top."""
    n = np.array(n, float); n /= np.linalg.norm(n)
    k.add(name, lathe(p - n * r * 0.3, n, [(0, 0), (r, 0), (r * 0.95, r * 0.35), (r * 0.55, r * 0.95), (r * 0.35, r * 0.9),
                                          (0, r * 0.45)], seg=20), BARN, bone, fuse=False, surface="shell")
    k.add(name + "hole", ell(p + n * r * 0.55, (r * 0.22, r * 0.22, r * 0.2)), HOLE, bone, fuse=False, surface="shell")


def eye_low(u, v):
    """The eye half lidded, the pupil low, looking down at the prey."""
    c = rp.eye_open(u, v, px=0.0, py=-0.3, pr=0.5)
    c[v > 0.2 - 0.12 * u] = srgb(BODY)
    c[np.abs(v - (0.2 - 0.12 * u)) < 0.1] = srgb("#3E4E5C")
    return c


def rapanor(src, out):
    k = Kit(src, coat="skin")

    # The foot: broad and long, running back under the shell; the lumpy body mass at the front under the hood
    def foot(V):
        V = V.copy()
        t = np.clip((V[:, 1] + 1) / 2, 0, 1)
        V[:, 2] *= 1 - 0.45 * t ** 1.5
        V[:, 0] *= (1 - 0.4 * t ** 2) * (1 + 0.05 * np.sin(V[:, 1] * 12))
        return V
    k.add("foot", ell((0, 0.04, 0.075), (0.24, 0.5, 0.08), deform=foot), BODY, "body")
    k.add("under", ell((0, 0.12, 0.25), (0.22, 0.3, 0.16)), BODY, "body")
    k.add("chest", ell((0, -0.2, 0.29), (0.22, 0.22, 0.22)), BODY, "body")
    k.add("neck", ell((0, -0.24, 0.44), (0.17, 0.17, 0.15)), BODY, "head")
    k.add("hood", ell(HOOD_C, HOOD_R), BODY, "head")
    k.add("hoodlip", ell(HOOD_C + (0, -0.085, -0.03), (0.16, 0.095, 0.072)), BODY, "head")
    # warts over the body, fused bumps
    rs = np.random.RandomState(11)
    for i in range(16):
        a = rs.uniform(-1.0, 1.0); z = rs.uniform(0.17, 0.42)
        c = np.array([0.215 * math.sin(a) * (1.02 - (z - 0.29) ** 2 * 3), -0.2 - 0.215 * math.cos(a) * 0.9, z])
        k.add(f"wart{i}", ell(c, (0.018, 0.018, 0.016)), BODY, "body")

    # The eye stalks drooping forward from the hood's top, the white balls on their tips
    rp.stalk(k, "stalk", [(0.06, -0.33, 0.64), (0.08, -0.38, 0.73), (0.095, -0.44, 0.75), BALL_C + (0, 0.03, 0.01)],
             [0.024, 0.021, 0.02, 0.019], (BALL_C, (BALL_R, BALL_R * 0.92, BALL_R)))

    # The great orange mouth under the hood: a lip of a ring, a funnel, a dark throat, a paler tongue
    a, b, n = frame(MOUTH_N)
    # (a funnel flaring to a thin lip, sunk into the body so the grey closes round its sides and the hood over it)
    k.add("funnel", lathe(MOUTH_C, n, [(0, -0.17), (0.09, -0.16), (0.15, -0.03), (0.168, 0.012), (0.155, 0.024),
                                       (0.12, 0.0), (0, -0.07)], seg=56), ORANGE, "head", fuse=False, surface="skin")
    k.add("throat", lathe(MOUTH_C, n, [(0, -0.075), (0.1, -0.026), (0.104, -0.008), (0, -0.055)], seg=48), THROAT,
          "head", fuse=False, surface="skin")
    # the tongue: a pale lump on the throat's floor
    k.add("tongue", ell(MOUTH_C + (0.004, 0, -0.052) - n * 0.04, (0.066, 0.042, 0.03)), TONGUE, "head", fuse=False,
          surface="skin")

    # Two thick lobed arms of the foot gripping the mussel under the mouth
    for s, (x0, y1, z1) in ((1, (0.13, -0.49, 0.16)), (-1, (-0.1, -0.52, 0.17))):
        k.add(f"arm{s}", tube([(0.17 * s, -0.26, 0.3), (0.17 * s, -0.38, 0.24), (x0, y1, z1)], [0.075, 0.065, 0.058]),
              BODY, "body")
        for j in range(3):
            k.add(f"finger{s}{j}", ell((x0 - s * 0.035 * (j - 1) * 0.9, y1 - 0.04, z1 + 0.04 - 0.03 * j),
                                       (0.03, 0.035, 0.026)), BODY, "body")
    # The mussel: two dark blue valves, a little apart, a paler line along each edge
    k.add("musselA", ell(MUS_C + (0, 0, 0.02), (0.175, 0.07, 0.05), rot=(0, -14, 8)), MUSSEL, "body", fuse=False,
          surface="shell")
    k.add("musselB", ell(MUS_C - (0, 0.012, 0.035), (0.165, 0.065, 0.045), rot=(0, -14, 8)), MUSSEL2, "body",
          fuse=False, surface="shell")
    k.add("musselline", ell(MUS_C + (0, -0.003, 0.0), (0.168, 0.06, 0.008), rot=(0, -14, 8)), MLINE, "body",
          fuse=False, surface="shell")

    # Speckles over the body, darker and paler
    parts = ["foot", "under", "chest", "neck", "hood", "arm", "finger", "wart"]
    rp.speckles(k, SPECK, ((-0.24, -0.55, 0.02), (0.24, 0.55, 0.65)), 70, 3, 0.01, 0.02, on=parts)
    rp.speckles(k, PALE, ((-0.24, -0.55, 0.02), (0.24, 0.55, 0.65)), 40, 4, 0.008, 0.014, on=parts)

    # The heavy shell: Rapanel's grown, deeper ridges, duller, crusted and barnacled on its top and +X side
    sh = rp.Shell(CC, r_end=0.29, wx=(0.054, 0.62), ridge=0.1, stretch=1.25)
    sh.add(k, colour=SHELL, band=BAND, lining=LINING, thick=0.016, band_w=0.05, lift=0.009)
    for i, (th, phi, dth, dphi) in enumerate(((20, 0.3, 40, 0.9), (75, 0.6, 30, 0.8), (115, 0.2, 25, 0.7),
                                              (-30, 0.9, 35, 0.7), (50, 1.2, 28, 0.6), (-80, 0.4, 40, 0.8),
                                              (140, 1.0, 20, 0.6), (5, -0.6, 30, 0.6), (95, -0.8, 25, 0.5))):
        crust(k, sh, th, phi, dth * 0.75, dphi * 0.7, i, lift=0.013)
    rs = np.random.RandomState(5)
    j = 0
    for th, phi in ((55, 0.75), (105, 1.25), (-20, 1.3), (15, 0.05)):
        for q in range(4):
            p, nn = on_shell(sh, th + rs.uniform(-7, 7), phi + rs.uniform(-0.18, 0.18))
            barnacle(k, f"barnacle{j}", p, nn, 0.032 + 0.012 * rs.rand())
            j += 1

    k.build(voxel=0.0082, smooth=4, band=0.008, wband=0.07)
    rp_board(k.ob)
    k.eye_states(lambda st: rp.lay_eyes(k, st, BALL_C, EYE_D, 0.031, look=eye_low))
    k.export(out)


def rp_board(ob):
    V = np.array([v.co[:] for v in ob.data.vertices])
    h, w, l = V[:, 2].max(), np.ptp(V[:, 0]), np.ptp(V[:, 1])
    sq = 1.3 * max(h, 0.85 * max(w, l))
    s = 0.853 * w + 0.522 * l
    print(f"BOARD: height {h:.3f} width {w:.3f} length {l:.3f}; corners {s:.3f} of square {sq:.3f} = {s / sq:.2f}")


if __name__ == "__main__":
    rapanor(*args())
